<?php
require_once __DIR__.'/../customer/booking_engine.php';requireRole(['owner']);$db=bdb();$uid=bookingUserId();$_SESSION['tm_owner_csrf']??=bin2hex(random_bytes(32));$notice='';$error='';
try{
 if($_SERVER['REQUEST_METHOD']==='POST'){
  if(!hash_equals($_SESSION['tm_owner_csrf'],(string)($_POST['csrf']??'')))throw new RuntimeException('Invalid session token.');
  $group=filter_var($_POST['group_id']??null,FILTER_VALIDATE_INT);$action=(string)($_POST['action']??'');if(!$group||!in_array($action,['confirmed','rejected','cancelled','completed'],true))throw new RuntimeException('Invalid action.');
  $db->beginTransaction();$q=$db->prepare('SELECT g.id,g.status FROM tm_booking_groups g JOIN turfs t ON t.id=g.turf_id JOIN facilities f ON f.id=t.facility_id WHERE g.id=? AND f.owner_id=? FOR UPDATE');$q->execute([$group,$uid]);$g=$q->fetch();if(!$g)throw new RuntimeException('Booking not found for your facility.');
  if(!in_array($g['status'],['pending','confirmed'],true))throw new RuntimeException('This booking is already closed.');
  if($g['status']==='pending'&&!in_array($action,['confirmed','rejected'],true))throw new RuntimeException('Pending bookings can only be confirmed or rejected.');
  if($g['status']==='confirmed'&&!in_array($action,['cancelled','completed'],true))throw new RuntimeException('Confirmed bookings can only be cancelled or completed.');
  $q=$db->prepare('UPDATE bookings b JOIN tm_booking_group_items i ON i.booking_id=b.id SET b.status=? WHERE i.group_id=?');$q->execute([$action,$group]);$q=$db->prepare('UPDATE tm_booking_groups SET status=? WHERE id=?');$q->execute([$action,$group]);$db->commit();$notice='Booking updated.';
 }
 $q=$db->prepare('SELECT g.*,t.name AS turf_name,u.name AS customer_name FROM tm_booking_groups g JOIN turfs t ON t.id=g.turf_id JOIN facilities f ON f.id=t.facility_id JOIN users u ON u.id=g.customer_id WHERE f.owner_id=? ORDER BY g.created_at DESC LIMIT 150');$q->execute([$uid]);$rows=$q->fetchAll();
}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();$rows=[];}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Online Bookings | TurfMate</title><link rel="stylesheet" href="../assets/css/booking.css"></head><body><header class="nav"><a class="logo" href="dashboard.php">⬡ TurfMate Owner</a><nav><a href="dashboard.php">Dashboard</a><a href="pricing_rules.php">Pricing Rules</a><a class="active" href="customer-bookings.php">Online Bookings</a></nav></header><main class="wrap"><div class="heading"><h1>Online booking requests</h1><p>Confirm or reject customer bookings. Overnight segments are updated together.</p></div><?php if($error):?><div class="alert"><?=esc($error)?></div><?php endif;?><?php if($notice):?><div class="success"><?=esc($notice)?></div><?php endif;?><div class="panel scroll"><table><thead><tr><th>ID</th><th>Customer</th><th>Turf</th><th>From</th><th>Until</th><th>Total</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td>#<?=esc($r['id'])?></td><td><?=esc($r['customer_name'])?></td><td><?=esc($r['turf_name'])?></td><td><?=esc($r['start_at'])?></td><td><?=esc($r['end_at'])?></td><td>Rs. <?=number_format((float)$r['total_amount'],2)?></td><td><?=esc($r['status'])?></td><td><?php $actions=$r['status']==='pending'?['confirmed'=>'Approve','rejected'=>'Reject']:($r['status']==='confirmed'?['completed'=>'Complete','cancelled'=>'Cancel']:[]);foreach($actions as $key=>$label):?><form method="post" style="display:inline-block"><input type="hidden" name="csrf" value="<?=esc($_SESSION['tm_owner_csrf'])?>"><input type="hidden" name="group_id" value="<?=esc($r['id'])?>"><input type="hidden" name="action" value="<?=esc($key)?>"><button class="btn btn-small" type="submit"><?=esc($label)?></button></form><?php endforeach;?></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><p>No online booking requests.</p><?php endif;?></div></main></body></html>
